starter.css:
.sessions {
  width: 660px; /* fixed for this exercise */
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}
.session-card {
  padding: 12px;
  border: 1px solid #e5e7eb;
  border-radius: 12px;
}
.session-card > * { margin: 0; }
.time { color: #6b7280; font-size: 0.85rem; }
h3 { font-size: 1rem; }
.room { font-weight: 600; color: #6d28d9; }

/* Make each card a row subgrid here */

solution.css:
.sessions {
  width: 660px; /* fixed for this exercise */
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}
.session-card {
  padding: 12px;
  border: 1px solid #e5e7eb;
  border-radius: 12px;
}
.session-card > * { margin: 0; }
.time { color: #6b7280; font-size: 0.85rem; }
h3 { font-size: 1rem; }
.room { font-weight: 600; color: #6d28d9; }

.session-card {
  display: grid;
  grid-row: span 4;
  grid-template-rows: subgrid;
  row-gap: 8px;
}
